// ============================================
// VALIDATION INPUT - MCP PDF Layout Translator
// RFC-014 Compliant with Optional Tracing Fields
// ============================================

const input = $input.first().json;
const body = input.body || input;

// Support RFC-014: data in context.* with fallback to root level
const ctx = body.context || {};

const errors = [];
const startTime = Date.now();

// --- OPTIONAL context fields (for tracing only, NO validation errors if missing) ---
const userId = body.user_id || ctx.user_id || null;
const guildId = body.guild_id || ctx.guild_id || null;
const userRequest = body.user_request || ctx.user_request || null;

// --- Required fields with RFC-014 context fallback ---
const fileUrl = body.file_url || ctx.file_url;
const fileBase64 = body.file_base64 || ctx.file_base64;
const mistralApiKey = body.mistral_api_key || ctx.mistral_api_key;
const anthropicApiKey = body.api_key || body.anthropic_api_key || ctx.api_key || ctx.anthropic_api_key;
const openaiApiKey = body.openai_api_key || ctx.openai_api_key;

// Validation of required fields
if (!fileUrl && !fileBase64) {
  errors.push('file_url or file_base64 required');
}
if (!mistralApiKey) {
  errors.push('mistral_api_key required');
}
if (!anthropicApiKey) {
  errors.push('api_key (Anthropic) required');
}
if (!openaiApiKey) {
  errors.push('openai_api_key required');
}

// MIME type detection functions
function detectMimeFromBase64(base64) {
  const prefix = base64.substring(0, 20);
  if (prefix.startsWith('/9j/')) return 'image/jpeg';
  if (prefix.startsWith('iVBOR')) return 'image/png';
  if (prefix.startsWith('R0lG')) return 'image/gif';
  if (prefix.startsWith('UklGR')) return 'image/webp';
  if (prefix.startsWith('Qk')) return 'image/bmp';
  if (prefix.startsWith('JVBER') || prefix.startsWith('JVBERi')) return 'application/pdf';
  return null;
}

function getMimeFromExtension(ext) {
  const map = {
    'jpg': 'image/jpeg', 'jpeg': 'image/jpeg',
    'png': 'image/png', 'gif': 'image/gif',
    'webp': 'image/webp', 'bmp': 'image/bmp',
    'tiff': 'image/tiff', 'tif': 'image/tiff',
    'pdf': 'application/pdf'
  };
  return map[(ext || '').toLowerCase()] || null;
}

// Prepare file URL with intelligent MIME detection
let preparedFileUrl = '';
let detectedMime = 'application/pdf';
const fileType = body.file_type || ctx.file_type;

if (fileUrl) {
  preparedFileUrl = fileUrl;
} else if (fileBase64) {
  // 1. Try from file_type param
  if (fileType) {
    detectedMime = getMimeFromExtension(fileType) || 'application/pdf';
  }
  // 2. Fallback: detect from magic bytes
  if (detectedMime === 'application/pdf') {
    const detected = detectMimeFromBase64(fileBase64);
    if (detected) detectedMime = detected;
  }
  preparedFileUrl = 'data:' + detectedMime + ';base64,' + fileBase64;
}

// Generate job ID
const jobId = 'job_' + Date.now().toString(36) + Math.random().toString(36).substring(2, 8);

// Return result with tracing fields
return [{
  json: {
    valid: errors.length === 0,
    errors: errors,
    jobId: jobId,
    fileUrl: preparedFileUrl,
    detectedMime: detectedMime,
    sourceLanguage: body.source_language || ctx.source_language || 'auto',
    targetLanguage: body.target_language || ctx.target_language || 'fr',
    mistralApiKey: mistralApiKey,
    anthropicApiKey: anthropicApiKey,
    openaiApiKey: openaiApiKey,
    callbackUrl: body.callback_url || ctx.callback_url || null,
    // Tracing fields (RFC-014)
    user_id: userId,
    guild_id: guildId,
    user_request: userRequest,
    startTime: startTime
  }
}];

